import { unstable_cache, revalidateTag } from 'next/cache';
import { getAllProducts } from '@/lib/db';

// Cache the product fetching with the 'products' tag
const getCachedProducts = unstable_cache(
  async () => getAllProducts(),
  ['all-products'], // keyParts
  { tags: ['products'] }
);

export default async function Page() {
  const products = await getCachedProducts();

  async function syncCatalog() {
    'use server';
    // Use 'max' profile to allow serving stale data while revalidating in background.
    // This ensures the admin experience remains responsive even during large sync jobs.
    revalidateTag('products', 'max'); 
  }

  return (
    <div className="p-8 font-sans">
      <h1 className="text-2xl font-bold mb-4">Product Catalog</h1>

      <div className="mb-8 p-6 bg-gray-50 border rounded-lg">
        <h2 className="text-lg font-semibold mb-4">Catalog Actions</h2>
        <form action={syncCatalog} className="flex flex-col gap-2 max-w-sm">
          <button 
            type="submit"
            className="px-4 py-2 bg-blue-600 text-white font-medium rounded hover:bg-blue-700 transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
          >
            Sync latest catalog
          </button>
          <p className="text-sm text-gray-500">
            Triggers a background refresh. You can continue working immediately.
          </p>
        </form>
      </div>

      <div className="bg-white shadow overflow-hidden border-b border-gray-200 sm:rounded-lg">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                ID
              </th>
              <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Name
              </th>
              <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Price
              </th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {products.map((product: any) => (
              <tr key={product.id}>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                  #{product.id}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                  {product.name}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                  ${product.price}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="mt-4 text-xs text-gray-400 text-right">
        Catalog data is cached. Sync to refresh.
      </div>
    </div>
  );
}

